        return []

    if start == goal:
        return [start]

    visited = [[False for _ in range(cols)] for _ in range(rows)]
    heap = []
    heapq.heappush(heap, (random.random(), start, [start]))

    while heap:
        priority, (row, col), path = heapq.heappop(heap)
        if (row, col) == goal:
            return path
        if visited[row][col]:
            continue
        visited[row][col] = True

        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        for dr, dc in directions:
            new_row, new_col = row + dr, col + dc
            if is_valid(new_row, new_col) and not visited[new_row][new_col]:
                new_path = path + [(new_row, new_col)]
                heapq.heappush(heap, (random.random(), (new_row, new_col), new_path))

    return []

