    parent = {}
    directions = [(-1,0), (1,0), (0,-1), (0,1)]
    found = False
    current = None
    while to_visit:
        current = to_visit.pop()
        if current in visited:
            continue
        visited.add(current)
        if current == goal:
            found = True
            break
        for dr, dc in directions:
            r, c = current[0] + dr, current[1] + dc
            if 0 <= r < rows and 0 <= c < cols:
                if grid[r][c] == '.' and (r, c) not in visited:
                    to_visit.add((r, c))
                    parent[(r, c)] = current
