        return [start]
    rows = len(grid)
    cols = len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    path = [start]
    visited = set([start])
    current = start
    max_steps = rows * cols * 4
    while current != goal:
        possible = []
        for dx, dy in directions:
            nx, ny = current[0] + dx, current[1] + dy
            if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] == '.' and (nx, ny) not in visited:
                possible.append((nx, ny))
        if not possible:
            if len(path) == 1:
                return []
            path.pop()
            current = path[-1]
            visited.remove(current)
        else:
            next_cell = random.choice(possible)
            path.append(next_cell)
            visited.add(next_cell)
            current = next_cell
        if len(path) > max_steps:
            return []
    return path

def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    # Check if start or goal are walls or out of bounds
    if (not (0 <= start[0] < rows and 0 <= start[1] < cols)) or grid[start[0]][start[1]] == '#':
        return []
    if (not (0 <= goal[0] < rows and 0 <= goal[1] < cols)) or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    INF = float('inf')
    distance = [[INF] * cols for _ in range(rows)]
    predecessor = [[None] * cols for _ in range(rows)]
    distance[start[0]][start[1]] = 0

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # Up, Down, Left, Right

    # Bellman-Ford algorithm to find shortest path
    for _ in range(rows * cols):
        updated = False
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == '#' or distance[r][c] == INF:
                    continue
                current_dist = distance[r][c]
                for dr, dc in directions:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                        if distance[nr][nc] > current_dist + 1:
                            distance[nr][nc] = current_dist + 1
                            predecessor[nr][nc] = (r, c)
                            updated = True
        if not updated:
            break

    # Check if goal is reachable
    if distance[goal[0]][goal[1]] == INF:
        return []

    # Reconstruct path
    path = []
    current = goal
    while current is not None:
        path.append(current)
        current = predecessor[current[0]][current[1]]
    path.reverse()

    return path

