    prev = {}
    visited = set()
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    found = False

    while heap:
        dist, r, c = heapq.heappop(heap)
        if (r, c) in visited:
            continue
        visited.add((r, c))
        if (r, c) == goal:
