    if rows == 0:
        return []
    cols = len(grid[0])

    # Check if start or goal is a wall
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    # Check if start is the same as goal
    if start == goal:
        return [start]

    # Initialize visited and parent matrices
    visited = [[False for _ in range(cols)] for _ in range(rows)]
    parent = [[None for _ in range(cols)] for _ in range(rows)]
    visited[start[0]][start[1]] = True

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Process the grid until no more changes
    while True:
        changed = False
        for row in range(rows):
            for col in range(cols):
                if visited[row][col]:
                    for dr, dc in directions:
                        nr, nc = row + dr, col + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if not visited[nr][nc] and grid[nr][nc] == '.':
                                visited[nr][nc] = True
                                parent[nr][nc] = (row, col)
                                changed = True
        if not changed:
            break

    # Check if the goal is reachable
    if not visited[goal[0]][goal[1]]:
        return []

    # Reconstruct path
    path = []
    current = goal
    while current is not None:
        path.append(current)
        current = parent[current[0]][current[1]]
    path.reverse()
    return path

def solve(grid, start, goal):
    import heapq

    if start == goal:
        r, c = start
        if grid[r][c] == '.':
            return [start]
        else:
            return []

    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0])
    if cols == 0:
        return []

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    INF = float('inf')
    distances = [[INF for _ in range(cols)] for _ in range(rows)]
    previous = [[None for _ in range(cols)] for _ in range(rows)]

    start_r, start_c = start
    distances[start_r][start_c] = 0
    heap = [(0, start_r, start_c)]
    heapq.heapify(heap)

    found = False
    goal_r, goal_c = goal

    while heap:
        current_dist, r, c = heapq.heappop(heap)
        if current_dist > distances[r][c]:
            continue
        if (r, c) == (goal_r, goal_c):
            found = True
            break
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                new_dist = current_dist + 1
                if new_dist < distances[nr][nc]:
                    distances[nr][nc] = new_dist
                    previous[nr][nc] = (r, c)
                    heapq.heappush(heap, (new_dist, nr, nc))

    if not found:
        return []

    path = []
    current = (goal_r, goal_c)
    while current is not None:
        path.append(current)
        current = previous[current[0]][current[1]]
    path.reverse()
    return path

