def solve(grid, start, goal):
    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0])

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    if not is_valid(*start) or not is_valid(*goal):
        return []

    if start == goal:
        return [start]

    reachable = [[False for _ in range(cols)] for _ in range(rows)]
    parents = [[None for _ in range(cols)] for _ in range(rows)]
    sr, sc = start
    reachable[sr][sc] = True

    changed = True
    while changed:
        changed = False
        for i in range(rows):
            for j in range(cols):
                if not reachable[i][j] and is_valid(i, j):
                    for dx, dy in [(-1,0), (1,0), (0,-1), (0,1)]:
                        ni = i + dx
                        nj = j + dy
                        if 0 <= ni < rows and 0 <= nj < cols:
                            if reachable[ni][nj]:
                                reachable[i][j] = True
                                parents[i][j] = (ni, nj)
                                changed = True
                                break

    gr, gc = goal
    if not reachable[gr][gc]:
        return []

    path = []
    current = goal
    while current is not None:
        path.append(current)
        current = parents[current[0]][current[1]]
    path.reverse()

    if path[0] != start:
        return []
    return path

