def solve(grid, start, goal):
    def is_wall(row, col):
        return (row < 0 or col < 0 or row >= len(grid) or col >= len(grid[0]) or
                grid[row][col] == '#')

    if is_wall(*start) or is_wall(*goal):
        return []
    if start == goal:
        return [start]

    queue = [ [start] ]
    while queue:
        path = random.choice(queue)
        queue.remove(path)
        current = path[-1]
        for dr, dc in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            nr, nc = current[0] + dr, current[1] + dc
            next_cell = (nr, nc)
            if is_wall(nr, nc) or next_cell in path:
                continue
            new_path = path + [next_cell]
            if next_cell == goal:
                return new_path
            queue.append(new_path)
    return []

