def solve(grid, start, goal):
    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0])

    def is_wall(r, c):
        return r < 0 or r >= rows or c < 0 or c >= len(grid[r]) or grid[r][c] == '#'

    if is_wall(*start) or is_wall(*goal):
        return []

    if start == goal:
        return [start]

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited = set()
    visited.add(start)
    path = [start]

    def backtrack(current, path, visited):
        for dr, dc in directions:
            next_row, next_col = current[0] + dr, current[1] + dc
            next_pos = (next_row, next_col)
            if next_pos == goal and not is_wall(next_row, next_col):
                return path + [next_pos]
            if not is_wall(next_row, next_col) and next_pos not in visited:
                visited.add(next_pos)
                path.append(next_pos)
                result = backtrack(next_pos, path, visited)
                if result:
                    return result
                path.pop()
                visited.remove(next_pos)
        return None

    result = backtrack(start, path, visited)
    return result if result is not None else []

