    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0])

    if start == goal:
        return [start] if grid[start[0]][start[1]] == '.' else []

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    # Direction deltas: 0=up, 1=right, 2=down, 3=left
    delta = [(-1, 0), (0, 1), (1, 0), (0, -1)]

    path = [start]
    directions = []
    current_dir = 0  # initial direction is up
    current_pos = start

    while True:
        found = False
        new_dir_options = []

        # Generate possible directions in priority order: right, forward, left, back
        for turn in ['right', 'forward', 'left', 'back']:
            if turn == 'right':
                new_dir = (current_dir + 1) % 4
            elif turn == 'forward':
                new_dir = current_dir
            elif turn == 'left':
                new_dir = (current_dir - 1) % 4
            else:
                new_dir = (current_dir - 2) % 4

            dr, dc = delta[new_dir]
            new_row = current_pos[0] + dr
            new_col = current_pos[1] + dc
            new_cell = (new_row, new_col)

            if 0 <= new_row < rows and 0 <= new_col < cols:
                if grid[new_row][new_col] == '#' or new_cell in path:
                    continue
                new_dir_options.append((new_dir, new_cell))

        if new_dir_options:
            new_dir, new_cell = new_dir_options[0]
            path.append(new_cell)
            directions.append(new_dir)
            current_dir = new_dir
            current_pos = new_cell
            found = True

            if current_pos == goal:
                return path

        if not found:
            if len(path) == 1:
                return []
            path.pop()
            last_dir = directions.pop()
            current_dir = (last_dir + 2) % 4  # opposite direction
            current_pos = path[-1]

